dy used primes\n        int newMask = mask | m;\n        long long cost = dpPrev[mask] + lcmll(a[i], cand[j]);\n        if(cost < dpCurr[newMask]){\n          dpCurr[newMask] = cost;\n          choice[i + 1][newMask] = cand[j];\n          preMask[i + 1][newMask] = mask;\n        }\n      }\n    }\n    dpPrev.swap(dpCurr);\n  }\n\n  long long best = INF; int bestMask = 0;\n  for(int mask = 0; mask < (1 << M); ++mask){\n    if(dpPrev[mask] < best){ best = dpPrev[mask]; bestMask = mask; }\n  }\n\n  vector<int> ans(n);\n  int curMask = bestMask;\n  for(int i = n; i >= 1; --i){\n    int val = choice[i][curMask];\n    if(val == -1) val = 1; // fallback (shouldn't happen in valid runs)\n    ans[i - 1] = val;\n    curMask = preMask[i][curMask];\n  }\n\n  for(int i = 0; i < n; ++i){\n    cout << ans[i] << (i + 1 == n ? '\\n' : ' ');\n  }\n  return 0;\n}\nEOF\n"
